<?php
namespace App\Http\Controllers;
use App\Models\Vehicle; use App\Models\VehicleMovement; use App\Models\User; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller { public function index(Request $r){ [$q,$filters]=$this->query($r); $movements=$q->paginate(30)->withQueryString(); $drivers=User::where('role','driver')->orderBy('name')->get(); $vehicles=Vehicle::orderBy('number')->get(); return view('reports.index',compact('movements','drivers','vehicles','filters')); } private function query(Request $r){$filters=$r->validate(['from'=>'nullable|date','to'=>'nullable|date','driver_id'=>'nullable|integer','vehicle_id'=>'nullable|integer','status'=>'nullable|in:out,returned','destination'=>'nullable|string|max:255']); $q=VehicleMovement::with(['vehicle','driver'])->when($filters['from']??null,fn($q,$v)=>$q->whereDate('departure_time','>=',$v))->when($filters['to']??null,fn($q,$v)=>$q->whereDate('departure_time','<=',$v))->when($filters['driver_id']??null,fn($q,$v)=>$q->where('user_id',$v))->when($filters['vehicle_id']??null,fn($q,$v)=>$q->where('vehicle_id',$v))->when($filters['status']??null,fn($q,$v)=>$q->where('status',$v))->when($filters['destination']??null,fn($q,$v)=>$q->where('destination','like','%'.$v.'%'))->latest('departure_time'); return [$q,$filters];} public function csv(Request $r): StreamedResponse {[$q]=$this->query($r); return response()->streamDownload(function() use($q){$out=fopen('php://output','w'); fwrite($out,"\xEF\xBB\xBF"); fputcsv($out,['شۆفێر','ئۆتۆمبێل','مەبەست','هۆکار','دەرچوون','گەڕانەوە','دۆخ','ماوە']); $q->chunk(500,function($rows)use($out){foreach($rows as $m) fputcsv($out,[$m->driver->name,$m->vehicle->number,$m->destination,$m->purpose,$m->departure_time?->format('Y-m-d H:i'),$m->return_time?->format('Y-m-d H:i'),$m->status,$m->duration_minutes!==null?floor($m->duration_minutes/60).' کاتژمێر '.$m->duration_minutes%60 .' خولەک':'']);}); fclose($out);},'vehicle-report-'.now()->format('Ymd-His').'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);} }
